// amped3 - build version (version.h). amped3_version.h is generated by CMake.

#include "version.h"

#include <amped3_version.h>

namespace amped3::version {

const char* Branch() { return AMPED3_VERSION_BRANCH; }
const char* Commit() { return AMPED3_VERSION_COMMIT; }
const char* Date() { return AMPED3_VERSION_DATE; }

std::string ShortCommit() {
  const std::string c = Commit();
  return c == "unknown" ? c : c.substr(0, 7);
}

std::string Text() {
  std::string branch = Branch();
  if (branch == "HEAD") branch = "detached";
  std::string s = branch + " " + ShortCommit();
  if (*Date()) s += std::string(" (") + Date() + ")";
  return s;
}

}  // namespace amped3::version
